"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[683],{83019(e,a,s){s.r(a),s.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/applications-of-qc","title":"\xbfPara qu\xe9 problemas son adecuados los computadores cu\xe1nticos?","description":"Aprende c\xf3mo decidimos qu\xe9 tipos de problemas podr\xedan beneficiarse de una soluci\xf3n cu\xe1ntica, y observa algunos ejemplos actuales de la comunidad.","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/applications-of-qc","permalink":"/learning/courses/quantum-computing-in-practice/applications-of-qc","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","tags":[],"version":"current","frontMatter":{"description":"Aprende c\xf3mo decidimos qu\xe9 tipos de problemas podr\xedan beneficiarse de una soluci\xf3n cu\xe1ntica, y observa algunos ejemplos actuales de la comunidad.","notebook_path":"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb","sidebar_label":"\xbfPara qu\xe9 problemas son adecuados los computadores cu\xe1nticos?","title":"\xbfPara qu\xe9 problemas son adecuados los computadores cu\xe1nticos?"},"sidebar":"tutorialsSidebar","previous":{"title":"QAOA a escala utilitaria","permalink":"/learning/courses/quantum-computing-in-practice/utility-scale-qaoa"},"next":{"title":"Mapeo (Mapping)","permalink":"/learning/courses/quantum-computing-in-practice/mapping"}}');var o=s(74848),i=s(28453);const r={description:"Aprende c\xf3mo decidimos qu\xe9 tipos de problemas podr\xedan beneficiarse de una soluci\xf3n cu\xe1ntica, y observa algunos ejemplos actuales de la comunidad.",notebook_path:"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb",sidebar_label:"\xbfPara qu\xe9 problemas son adecuados los computadores cu\xe1nticos?",title:"\xbfPara qu\xe9 problemas son adecuados los computadores cu\xe1nticos?"},c=void 0,t={},l=[{value:"Introducci\xf3n",id:"introduction",level:2},{value:"Dificultad cl\xe1sica vs. cu\xe1ntica",id:"classical-vs-quantum-difficulty",level:2},{value:"Clases de complejidad",id:"complexity-classes",level:3},{value:"Los computadores cu\xe1nticos de hoy y sus l\xedmites",id:"todays-quantum-computers-and-their-limits",level:3},{value:"\xc1reas de aplicaci\xf3n y casos de uso",id:"application-areas-and-use-cases",level:2},{value:"Caso de uso 1: Simulaci\xf3n de la din\xe1mica de hadrones",id:"use-case-1-simulating-hadron-dynamics",level:3},{value:"Caso de uso 2: Optimizaci\xf3n de un vidrio de esp\xedn de Ising",id:"use-case-2-optimization-of-an-ising-spin-glass",level:3},{value:"Caso de uso 3: Predicci\xf3n de la estructura secundaria del ARNm",id:"use-case-3-mrna-secondary-structure-prediction",level:3},{value:"Conclusi\xf3n",id:"conclusion",level:2}];function d(e){const a={a:"a",annotation:"annotation",h2:"h2",h3:"h3",img:"img",li:"li",math:"math",mi:"mi",mn:"mn",mo:"mo",mrow:"mrow",ol:"ol",p:"p",semantics:"semantics",span:"span",ul:"ul",...(0,i.R)(),...e.components},{IBMVideo:n}=a;return n||function(e,a){throw new Error("Expected "+(a?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,o.jsxs)(o.Fragment,{children:["\n","\n",(0,o.jsxs)(a.p,{children:["Mira el video sobre aplicaciones de la computaci\xf3n cu\xe1ntica de Olivia Lanes, o \xe1brelo en una ventana separada en ",(0,o.jsx)(a.a,{href:"https://youtu.be/33QmsXhIlpU",children:"YouTube."})]}),"\n",(0,o.jsx)(n,{id:"134063426",title:"En este video, Olivia Lanes describe varias aplicaciones posibles de la computaci\xf3n cu\xe1ntica a escala de utilidad. Entre ellas se incluyen la simulaci\xf3n de hadrones y vidrios de esp\xedn, as\xed como el modelado de estructuras de prote\xednas."}),"\n",(0,o.jsx)(a.h2,{id:"introduction",children:"Introducci\xf3n"}),"\n",(0,o.jsx)(a.p,{children:"En la lecci\xf3n anterior, nos sumergimos en profundidad en un \xfanico problema -- resolver el problema de optimizaci\xf3n Max-Cut utilizando la formulaci\xf3n QUBO. Hoy tomaremos un camino diferente y discutiremos aplicaciones a corto plazo en un marco m\xe1s amplio. Comenzaremos d\xe1ndote una idea de c\xf3mo decidimos qu\xe9 tipos de problemas podr\xedan beneficiarse de una soluci\xf3n cu\xe1ntica. Luego veremos algunos trabajos recientes de nuestra comunidad. Esto deber\xeda ayudarte a desarrollar una intuici\xf3n para los diferentes tipos de problemas de computaci\xf3n cu\xe1ntica y a comprender c\xf3mo los abordamos."}),"\n",(0,o.jsx)(a.h2,{id:"classical-vs-quantum-difficulty",children:"Dificultad cl\xe1sica vs. cu\xe1ntica"}),"\n",(0,o.jsx)(a.p,{children:"Antes de entrar en los ejemplos, hablemos primero de c\xf3mo examinamos y clasificamos la dificultad de diferentes problemas. Algunos problemas se resuelven f\xe1cilmente en un computador cl\xe1sico, y no necesitamos un computador cu\xe1ntico para ellos. Por otro lado, hay problemas muy dif\xedciles para los cuales los computadores cu\xe1nticos son necesarios. Un ejemplo conocido es la factorizaci\xf3n de n\xfameros enteros enormes. El cifrado RSA se basa en la dificultad de este problema, y el algoritmo de Shor fue dise\xf1ado para resolverlo en un computador cu\xe1ntico. Otro ejemplo es la b\xfasqueda de una soluci\xf3n en un conjunto de datos no ordenado -- esto puede resolverse te\xf3ricamente mediante el algoritmo cu\xe1ntico conocido como algoritmo de Grover. Sin embargo, la mayor\xeda de los expertos coinciden en que estos tipos de algoritmos requieren la implementaci\xf3n de correcci\xf3n de errores y la tecnolog\xeda a\xfan no est\xe1 lista para ello."}),"\n",(0,o.jsx)(a.p,{children:"As\xed que buscamos problemas que podamos abordar en alg\xfan punto intermedio entre muy f\xe1cil y muy dif\xedcil -- aquellos que los computadores cu\xe1nticos de hoy pueden manejar, pero que representan dificultades para los computadores cl\xe1sicos."}),"\n",(0,o.jsx)(a.h3,{id:"complexity-classes",children:"Clases de complejidad"}),"\n",(0,o.jsx)(a.p,{children:"La dificultad de estos problemas se categoriza y analiza en un subcampo de la inform\xe1tica llamado teor\xeda de la complejidad computacional. Hay una variedad de clases de complejidad diferentes en la computaci\xf3n cl\xe1sica, pero algunas de las m\xe1s fundamentales son:"}),"\n",(0,o.jsxs)(a.ul,{children:["\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:"P: Problemas que son solubles en tiempo polinomial a medida que aumenta el tama\xf1o del problema. Son f\xe1ciles de resolver."}),"\n"]}),"\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:"NP: Esto significa polinomial no determinista. Estos problemas no pueden resolverse necesariamente en tiempo polinomial, pero sus respuestas pueden verificarse en tiempo polinomial."}),"\n"]}),"\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:"NP-completo son los problemas m\xe1s dif\xedciles en NP y no tienen una soluci\xf3n polinomial conocida. Aqu\xed viven problemas famosos como el problema del viajante y el juego Sudoku."}),"\n"]}),"\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:"BPP, o Problemas Polinomiales con Error Acotado, que pueden ser resueltos por un computador cl\xe1sico probabil\xedstico en tiempo polinomial dentro de un cierto margen de error."}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(a.p,{children:"Cuando se invent\xf3 el concepto de computaci\xf3n cu\xe1ntica, muchos investigadores realizaron esfuerzos considerables para determinar qu\xe9 clase de problemas estos nuevos tipos de computadores podr\xedan resolver eficientemente. Se introdujo una nueva clase de problemas:"}),"\n",(0,o.jsxs)(a.ul,{children:["\n",(0,o.jsx)(a.li,{children:"BQP, o Problemas Polinomiales Cu\xe1nticos con Error Acotado. Este es el equivalente cu\xe1ntico de BPP: es la clase de problemas de decisi\xf3n que son solubles por un computador cu\xe1ntico en tiempo polinomial con una peque\xf1a probabilidad de error."}),"\n"]}),"\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.img,{alt:"Relaciones supuestas entre clases de complejidad",src:s(52600).A+"",width:"976",height:"682"})}),"\n",(0,o.jsx)(a.p,{children:"Todas estas clases viven dentro de una clase mayor que llamamos PSPACE. Arriba hay un diagrama de las relaciones supuestas entre algunas clases de complejidad, pero esto es matem\xe1ticamente muy dif\xedcil de demostrar definitivamente. Notar\xe1s que BQP no necesariamente se superpone con NP-completo. Sin embargo, existen enfoques de computaci\xf3n cu\xe1ntica que intentan resolver problemas en NP-completo."}),"\n",(0,o.jsx)(a.p,{children:"Un malentendido com\xfan es que no tiene sentido explorar soluciones cu\xe1nticas para problemas para los cuales no se ha encontrado una prueba matem\xe1tica de aceleraci\xf3n cu\xe1ntica. Pero encontrar una prueba matem\xe1tica de que un algoritmo cu\xe1ntico es m\xe1s r\xe1pido que su contraparte cl\xe1sica es dif\xedcil. Shor y Grover son dos de los pocos ejemplos hasta ahora donde esto se ha logrado. De hecho, la demostraci\xf3n rigurosa de que P y NP son diferentes es una de las preguntas abiertas m\xe1s conocidas en toda la matem\xe1tica, aunque toda la intuici\xf3n sugiere que debe ser as\xed."}),"\n",(0,o.jsx)(a.p,{children:"Sin embargo, la forma en que un algoritmo escala con el crecimiento del tama\xf1o del problema -- lo que se refleja en la clase de complejidad -- no es siempre la caracter\xedstica m\xe1s relevante de un algoritmo. Esta escalabilidad es a menudo el escenario del peor caso. Es perfectamente posible que en la pr\xe1ctica no encontremos el escenario del peor caso con mayor frecuencia."}),"\n",(0,o.jsx)(a.p,{children:"Solo porque las demostraciones de dificultad son complicadas no significa que no podamos progresar. Introducimos la idea de soluciones heur\xedsticas. Si eres experimentalista, probablemente conoces y amas este tipo de soluciones. Una heur\xedstica es cualquier enfoque para resolver un problema que es pragm\xe1tico pero no necesariamente \xf3ptimo, ya que las soluciones no necesitan ser \xf3ptimas para ser \xfatiles. Piensa, por ejemplo, en aplicaciones financieras. A\xfan no hemos encontrado una aceleraci\xf3n exponencial para la mayor\xeda de los algoritmos financieros donde se podr\xeda usar lo cu\xe1ntico, pero no necesitamos una soluci\xf3n \xf3ptima. En finanzas, incluso una soluci\xf3n que sea solo un 0,1% m\xe1s eficiente podr\xeda significar miles de millones de d\xf3lares de ganancia."}),"\n",(0,o.jsx)(a.h3,{id:"todays-quantum-computers-and-their-limits",children:"Los computadores cu\xe1nticos de hoy y sus l\xedmites"}),"\n",(0,o.jsx)(a.p,{children:"Entonces, \xbfc\xf3mo sabemos qu\xe9 casos de uso y problemas podr\xedan ser adecuados actualmente para la computaci\xf3n cu\xe1ntica? \xbfHay buenas razones para creer que la utilidad cu\xe1ntica o incluso la ventaja cu\xe1ntica pueden encontrarse ahora o en un futuro cercano?"}),"\n",(0,o.jsx)(a.p,{children:"Quiz\xe1s es m\xe1s f\xe1cil empezar nombrando las cosas que el problema definitivamente no deber\xeda tener. No puede requerir una cantidad enorme de qubits. Todav\xeda no tenemos procesadores con miles o millones de qubits disponibles. Esa es una de las principales razones por las que el algoritmo de Shor y similares est\xe1n todav\xeda tan lejos de la realizaci\xf3n. Los circuitos tampoco pueden ser demasiado profundos. El l\xedmite de profundidad del circuito depende de muchos factores, pero en general, si tu experimento requiere una profundidad que a\xfan no has visto en la literatura, probablemente no funcionar\xe1. Y finalmente, a\xfan no pueden implementarse algoritmos que sabemos que requieren correcci\xf3n de errores."}),"\n",(0,o.jsxs)(a.p,{children:["Todas estas limitaciones se abordan en la ",(0,o.jsx)(a.a,{href:"https://www.ibm.com/quantum/technology#roadmap",children:"hoja de ruta de IBM Quantum\xae"}),", y esperamos alcanzar la correcci\xf3n de errores a principios de la d\xe9cada de 2030. Por ahora, sin embargo, debemos buscar experimentos que utilicen la mayor\xeda de los qubits actualmente disponibles en un QPU. Tambi\xe9n enfatizamos la importancia de la mitigaci\xf3n de errores y la supresi\xf3n de errores. Y finalmente, deber\xeda haber una extensi\xf3n obvia a futuras aplicaciones que ser\xedan importantes para la sociedad y que en \xfaltima instancia podr\xedan llevarnos a una ventaja cu\xe1ntica."]}),"\n",(0,o.jsx)(a.h2,{id:"application-areas-and-use-cases",children:"\xc1reas de aplicaci\xf3n y casos de uso"}),"\n",(0,o.jsx)(a.p,{children:"Hablemos ahora sobre algunos ejemplos de casos de uso que caen en tres categor\xedas principales que hemos identificado como las m\xe1s probables para resultados favorables a corto y mediano plazo:"}),"\n",(0,o.jsxs)(a.ol,{children:["\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsxs)(a.p,{children:["Simulaciones de la naturaleza. Los m\xe9todos cl\xe1sicos actuales de simulaciones at\xf3micas y moleculares est\xe1n limitados por descripciones matem\xe1ticas ineficientes de la estructura at\xf3mica. Almacenar y manipular un estado cu\xe1ntico requiere exponencialmente muchos recursos en una computadora cl\xe1sica, pero puede hacerse de manera eficiente en una computadora cu\xe1ntica. Esto podr\xeda llevar a desarrollos en la captura de di\xf3xido de carbono, bater\xedas alternativas o la invenci\xf3n de nuevos f\xe1rmacos. Algunos algoritmos que son especialmente relevantes en esta \xe1rea son: el Variational Quantum Eigensolver (VQE), que se usa para estimar ciertas propiedades de un material, como estados de equilibrio o de energ\xeda m\xednima; el algoritmo de Simulaci\xf3n de Din\xe1mica Temporal (TDS), que se usa para estimar funciones de respuesta o propiedades espectrales de materiales; y un reci\xe9n llegado, ",(0,o.jsx)(a.a,{href:"/learning/courses/quantum-diagonalization-algorithms/sqd-overview",children:"Sample-based Quantum Diagonalization (SQD)"}),", del que creemos que oiremos hablar mucho m\xe1s en un futuro cercano."]}),"\n"]}),"\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:"Optimizaci\xf3n. Esta \xe1rea es ubicua en la computaci\xf3n, por lo que los casos de uso son numerosos y variados. Algunos ejemplos de los que o\xedmos hablar mucho son la optimizaci\xf3n de carteras en finanzas, el dise\xf1o industrial y la distribuci\xf3n y cadena de suministro. El algoritmo m\xe1s com\xfan que probablemente escuchar\xe1s relacionado con las finanzas es el que ya hemos cubierto con cierta profundidad: el algoritmo de optimizaci\xf3n aproximada cu\xe1ntica, o QAOA."}),"\n"]}),"\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:"Aprendizaje autom\xe1tico cu\xe1ntico. Esta \xe1rea ha generado mucha emoci\xf3n en los \xfaltimos a\xf1os, pero es probable que QML no sea \xfatil tan pronto como lo ser\xe1 la simulaci\xf3n. Sin embargo, existen algunos algoritmos impresionantes en los que se est\xe1 trabajando para abordar algunos casos de uso muy importantes. Algunos de estos posibles casos de uso son el procesamiento del lenguaje natural, el an\xe1lisis del tr\xe1fico de red e incluso la detecci\xf3n de fraude en transacciones financieras. Los algoritmos relevantes en esta \xe1rea son la m\xe1quina de vectores de soporte cu\xe1ntica (QSVM), las redes neuronales cu\xe1nticas (QNN) y las redes generativas antag\xf3nicas cu\xe1nticas."}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(a.p,{children:"Dentro de estas amplias \xe1reas de aplicaci\xf3n, la comunidad ve el beneficio de que grupos colaboren centr\xe1ndose en un tema m\xe1s espec\xedfico. IBM\xae ha lanzado una iniciativa llamada Working Groups para ayudar a los colaboradores a encontrarse mutuamente y crear sinergias productivas en cuatro \xe1reas espec\xedficas: salud y ciencias de la vida, materiales y computaci\xf3n de alto rendimiento (HPC), f\xedsica de altas energ\xedas y optimizaci\xf3n. Recientemente tambi\xe9n se cre\xf3 un quinto Working Group sobre sostenibilidad."}),"\n",(0,o.jsx)(a.p,{children:"Ahora vamos a examinar m\xe1s de cerca algunos problemas que han sido trabajados recientemente por algunos de estos Working Groups. El objetivo principal aqu\xed no es entender cada detalle de un experimento -- eso puede ser dif\xedcil incluso para expertos cuando el art\xedculo queda ligeramente fuera de su \xe1rea de especializaci\xf3n. El objetivo es simplemente desarrollar una intuici\xf3n para los tipos de problemas para los que los computadores cu\xe1nticos son adecuados y c\xf3mo los abordamos. Y si te interesa, te animamos a leer los art\xedculos completos."}),"\n",(0,o.jsx)(a.h3,{id:"use-case-1-simulating-hadron-dynamics",children:"Caso de uso 1: Simulaci\xf3n de la din\xe1mica de hadrones"}),"\n",(0,o.jsxs)(a.p,{children:["Primero, profundizaremos en un art\xedculo del grupo de Martin Savage en la Universidad de Washington, titulado ",(0,o.jsx)(a.a,{href:"https://journals.aps.org/prd/abstract/10.1103/PhysRevD.109.114510",children:"Quantum Simulations of Hadron Dynamics in the Schwinger Model Using 112 Qubits"}),"."]}),"\n",(0,o.jsx)(a.p,{children:'Aunque no seas f\xedsico de altas energ\xedas, quiz\xe1s est\xe9s familiarizado con el t\xe9rmino "hadr\xf3n", como en el Gran Colisionador de Hadrones (LHC), el enorme acelerador de part\xedculas con una circunferencia de 27 km que finalmente permiti\xf3 observar el bos\xf3n de Higgs. Un hadr\xf3n es una part\xedcula subat\xf3mica compuesta formada por otras part\xedculas peque\xf1as llamadas quarks. Algunos ejemplos de hadrones son los neutrones y los protones.'}),"\n",(0,o.jsx)(a.p,{children:"Para contexto: el LHC fue construido para permitir el estudio de la f\xedsica fundamental haciendo colisionar part\xedculas a energ\xedas extremadamente altas. Con el LHC, los cient\xedficos esperan aprender m\xe1s sobre el universo temprano y las leyes fundamentales de la naturaleza. En principio, las interacciones de estas part\xedculas podr\xedan simularse de principio a fin con un computador cu\xe1ntico suficientemente potente. A\xfan no estamos del todo ah\xed, pero estamos progresando."}),"\n",(0,o.jsx)(a.p,{children:"El modelo de Schwinger es un modelo popular y sencillo utilizado para simular algunas de estas din\xe1micas. Es un modelo que describe el comportamiento de electrones y positrones interactuando en 1+1D a trav\xe9s de fotones, es decir, en tiempo y una dimensi\xf3n espacial. El modelo tiene muchas similitudes con la cromodin\xe1mica cu\xe1ntica (QCD), que describe c\xf3mo interact\xfaan los quarks y hadrones, pero la QCD es extremadamente dif\xedcil de simular. Por lo tanto, el modelo de Schwinger se usa a menudo como modelo de juguete para investigar algunos fen\xf3menos que comparten ambos."}),"\n",(0,o.jsx)(a.p,{children:"Para entender por qu\xe9 abordaron este problema, plante\xe9monos una serie de preguntas."}),"\n",(0,o.jsx)(a.p,{children:"Primero, \xbfpor qu\xe9 ten\xedan razones para creer que la simulaci\xf3n de esto en un computador cu\xe1ntico funcionar\xeda en absoluto? En este caso, los electrones y positrones en el modelo de Schwinger tienen un efecto de apantallamiento que hace que las correlaciones entre fermiones distantes disminuyan exponencialmente con la distancia. Esto significa que no hay tantas interacciones de largo alcance necesarias de un qubit en un lado del chip al otro, lo cual se sabe que es muy propenso a errores. As\xed que esto es ideal para el hardware que tenemos hoy."}),"\n",(0,o.jsx)(a.p,{children:"A continuaci\xf3n: \xbfPor qu\xe9 es de inter\xe9s este tema? La f\xedsica de altas energ\xedas es generalmente de gran inter\xe9s. La gente ha estado dispuesta a gastar miles de millones de d\xf3lares para construir el LHC, y muchos miles de cient\xedficos y t\xe9cnicos en todo el mundo han dedicado sus carreras a este campo. Aunque el modelo de Schwinger es simplista y no est\xe1 dise\xf1ado para tres dimensiones espaciales, sigue siendo una simplificaci\xf3n \xfatil de la teor\xeda completa."}),"\n",(0,o.jsx)(a.p,{children:"Finalmente: \xbfC\xf3mo se realiz\xf3 este trabajo, o c\xf3mo abordar\xedamos el problema si quisi\xe9ramos continuar este trabajo? En los experimentos de simulaci\xf3n, VQE es uno de los enfoques m\xe1s comunes, y el primer paso es casi siempre el mismo: preparar el estado fundamental. En este caso, se trata de un estado de vac\xedo. En este experimento utilizan una nueva versi\xf3n de VQE llamada SC-ADAPT-VQE (que significa Scalable Circuits - Adaptive Derivative-Assembled Pseudo-Trotter ansatz-VQE), para preparar tanto el estado fundamental como el paquete de ondas del hadr\xf3n sobre ese vac\xedo. El siguiente paso consiste en dejar que los hadrones evolucionen en el tiempo. Finalmente, se identifican y miden los observables de inter\xe9s."}),"\n",(0,o.jsx)(a.p,{children:"Si estos pasos -- aparte de la parte del paquete de ondas del hadr\xf3n -- suenan algo familiares, es porque son muy similares a lo que cubrimos en el ejemplo de QAOA en la lecci\xf3n anterior. Comenzamos en un estado conocido (aqu\xed el estado de vac\xedo) y luego lo dejamos evolucionar en el tiempo con una serie de hamiltonianos exponenciados. Muchos algoritmos variacionales siguen este enfoque general. Una gran diferencia aqu\xed, sin embargo, es que creamos el paquete de ondas del hadr\xf3n centrado en nuestro circuito antes de dejarlo evolucionar."}),"\n",(0,o.jsx)(a.p,{children:"Entonces, \xbfc\xf3mo creamos el paquete de ondas? Sobre el vac\xedo, un hadr\xf3n puede excitarse creando un par fermi\xf3n-antifermi\xf3n en sitios de red adyacentes. Al preparar una superposici\xf3n de tales hadrones en diferentes posiciones, se puede preparar un paquete de ondas arbitrario. Los autores centraron su paquete de ondas en el medio del circuito para observar la evoluci\xf3n sin alcanzar un l\xedmite."}),"\n",(0,o.jsx)(a.p,{children:"Pero recuerda: lo importante al trabajar con QPUs ruidosos es mantener la profundidad del circuito manejable. Para ello, el protocolo SC-ADAPT-VQE utiliza simetr\xedas y jerarqu\xedas en escalas de longitud para determinar circuitos cu\xe1nticos de baja profundidad para la preparaci\xf3n de estados. Esto produce un ansatz con un n\xfamero menor de par\xe1metros y por lo tanto una menor profundidad."}),"\n",(0,o.jsx)(a.p,{children:"El experimento se realiz\xf3 en un dispositivo IBM Quantum Heron e incluy\xf3 varios tipos de mitigaci\xf3n y supresi\xf3n de errores: Dynamical Decoupling, Zero Noise Extrapolation, Pauli Twirling y una t\xe9cnica recientemente desarrollada llamada Operator Decoherence Renormalization."}),"\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.img,{alt:"Resultados de las simulaciones de hadrones",src:s(77894).A+"",width:"1158",height:"838"})}),"\n",(0,o.jsx)(a.p,{children:"Arriba hay una figura del art\xedculo que muestra el observable de inter\xe9s, el condensado quiral, que es esencialmente una fase superfluida de los hadrones. Podemos ver el paquete de ondas en el centro de los sitios de red designados para este experimento. Las l\xedneas negras son los resultados libres de errores de la simulaci\xf3n cl\xe1sica (computacionalmente costosa), mientras que los puntos con barras de error son los resultados del computador cu\xe1ntico IBM de 133 qubits Torino."}),"\n",(0,o.jsxs)(a.p,{children:["Vemos dos pasos de tiempo diferentes en la evoluci\xf3n del paquete de ondas. En el tiempo ",(0,o.jsxs)(a.span,{className:"katex",children:[(0,o.jsx)(a.span,{className:"katex-mathml",children:(0,o.jsx)(a.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,o.jsxs)(a.semantics,{children:[(0,o.jsxs)(a.mrow,{children:[(0,o.jsx)(a.mi,{children:"t"}),(0,o.jsx)(a.mo,{children:"="}),(0,o.jsx)(a.mn,{children:"1"})]}),(0,o.jsx)(a.annotation,{encoding:"application/x-tex",children:"t=1"})]})})}),(0,o.jsxs)(a.span,{className:"katex-html","aria-hidden":"true",children:[(0,o.jsxs)(a.span,{className:"base",children:[(0,o.jsx)(a.span,{className:"strut",style:{height:"0.6151em"}}),(0,o.jsx)(a.span,{className:"mord mathnormal",children:"t"}),(0,o.jsx)(a.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,o.jsx)(a.span,{className:"mrel",children:"="}),(0,o.jsx)(a.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,o.jsxs)(a.span,{className:"base",children:[(0,o.jsx)(a.span,{className:"strut",style:{height:"0.6444em"}}),(0,o.jsx)(a.span,{className:"mord",children:"1"})]})]})]}),", el condensado quiral es estrecho y localizado, y tambi\xe9n concuerda bien con la simulaci\xf3n cl\xe1sica. En ",(0,o.jsxs)(a.span,{className:"katex",children:[(0,o.jsx)(a.span,{className:"katex-mathml",children:(0,o.jsx)(a.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,o.jsxs)(a.semantics,{children:[(0,o.jsxs)(a.mrow,{children:[(0,o.jsx)(a.mi,{children:"t"}),(0,o.jsx)(a.mo,{children:"="}),(0,o.jsx)(a.mn,{children:"14"})]}),(0,o.jsx)(a.annotation,{encoding:"application/x-tex",children:"t=14"})]})})}),(0,o.jsxs)(a.span,{className:"katex-html","aria-hidden":"true",children:[(0,o.jsxs)(a.span,{className:"base",children:[(0,o.jsx)(a.span,{className:"strut",style:{height:"0.6151em"}}),(0,o.jsx)(a.span,{className:"mord mathnormal",children:"t"}),(0,o.jsx)(a.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,o.jsx)(a.span,{className:"mrel",children:"="}),(0,o.jsx)(a.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,o.jsxs)(a.span,{className:"base",children:[(0,o.jsx)(a.span,{className:"strut",style:{height:"0.6444em"}}),(0,o.jsx)(a.span,{className:"mord",children:"14"})]})]})]}),", est\xe1 mucho m\xe1s extendido. La comparaci\xf3n con el simulador ya no es tan perfecta, pero a\xfan se puede reconocer una muy buena concordancia entre teor\xeda y datos, lo cual es alentador."]}),"\n",(0,o.jsx)(a.p,{children:"En resumen, este es un ejemplo muy interesante del tipo de trabajo de simulaci\xf3n que quiz\xe1s no pensar\xedas inicialmente en aplicar la computaci\xf3n cu\xe1ntica, pero que muestra un verdadero potencial. No es perfecto, pero no necesitas ser un experto en f\xedsica de part\xedculas para ver que el computador cu\xe1ntico predice con precisi\xf3n la propagaci\xf3n hacia el exterior del paquete de ondas, que es exactamente lo que esperar\xedamos. Con suerte, el trabajo futuro en esta \xe1rea continuar\xe1, y los f\xedsicos de altas energ\xedas seguir\xe1n encontrando formas de incorporar la computaci\xf3n cu\xe1ntica en sus flujos de trabajo. El objetivo es resolver problemas te\xf3ricos dif\xedciles con mayor precisi\xf3n y usar experimentos para confirmar o descartar teor\xedas, con la esperanza de descubrir nueva f\xedsica, construir detectores mejorados y llegar a una mejor comprensi\xf3n de la naturaleza en su nivel m\xe1s fundamental."}),"\n",(0,o.jsx)(a.h3,{id:"use-case-2-optimization-of-an-ising-spin-glass",children:"Caso de uso 2: Optimizaci\xf3n de un vidrio de esp\xedn de Ising"}),"\n",(0,o.jsxs)(a.p,{children:["Nuestro siguiente ejemplo se centra en la optimizaci\xf3n y ser\xe1 un an\xe1lisis profundo de un art\xedculo llamado ",(0,o.jsx)(a.a,{href:"https://arxiv.org/abs/2405.13898",children:"Bias-Field Digitized Counterdiabatic Quantum Optimization"}),", realizado por miembros del equipo de Kipu Quantum y la Universidad del Pa\xeds Vasco en Espa\xf1a."]}),"\n",(0,o.jsx)(a.p,{children:'En el art\xedculo, los autores desarrollaron un nuevo m\xe9todo de optimizaci\xf3n y lo aplicaron para encontrar el estado fundamental de un vidrio de esp\xedn de Ising. Como ya se discuti\xf3, muchos problemas de optimizaci\xf3n combinatoria pueden reformularse como la resoluci\xf3n de estados de baja energ\xeda de hamiltonianos de Ising. El modelo de Ising describe la interacci\xf3n de una disposici\xf3n de espines microsc\xf3picos. En algunos reg\xedmenes, el modelo predice que los espines se comportan como un vidrio, donde los momentos magn\xe9ticos est\xe1n desordenados por encima de una llamada "temperatura de congelaci\xf3n".'}),"\n",(0,o.jsx)(a.p,{children:"Comenzamos como antes con una serie de definiciones. La primera es contradiab\xe1tico (counterdiabatic), que es un tipo de evoluci\xf3n que suprime los efectos no adiab\xe1ticos de un sistema, independientemente de lo r\xe1pido que ocurran estos procesos. Recuerda el teorema adiab\xe1tico del episodio anterior -- normalmente necesitas evolucionar un sistema muy lentamente si quieres que permanezca en el estado fundamental. Eso es un gran problema, porque cuanto m\xe1s lento necesitamos evolucionar las cosas, m\xe1s tiempo tenemos para errores. El Counterdiabatic Driving (CD) tiene como objetivo combatir esto a\xf1adiendo t\xe9rminos que contrarrestan estas excitaciones no deseadas. La idea b\xe1sica es acelerar todo el experimento y reducir la profundidad del circuito suprimiendo excitaciones que podr\xedan causar transiciones no deseadas."}),"\n",(0,o.jsx)(a.p,{children:"Ahora pasamos al otro t\xe9rmino t\xe9cnico del t\xedtulo: el campo de sesgo (bias field). Otros algoritmos iterativos, como VQE, introducen par\xe1metros cl\xe1sicos en los estados y usan optimizadores cl\xe1sicos para buscar en el espacio de par\xe1metros de alta dimensi\xf3n el conjunto de par\xe1metros que produce un valor esperado m\xednimo para un hamiltoniano fijo. En este caso, en lugar de eso, var\xedan el hamiltoniano cada vez y se mueven adiab\xe1ticamente desde un caso conocido al caso de inter\xe9s. Para cambiar el hamiltoniano, simplemente aplican el valor esperado de Pauli-Z de una iteraci\xf3n directamente como campo de sesgo en el hamiltoniano para la siguiente iteraci\xf3n. De esta manera, dirigen la din\xe1mica hacia la soluci\xf3n real sin necesidad de optimizadores cl\xe1sicos."}),"\n",(0,o.jsx)(a.p,{children:"Entonces, \xbfpor qu\xe9 es interesante este experimento? Los vidrios de esp\xedn de Ising son de inter\xe9s fundamental en la f\xedsica, pero este nuevo enfoque es a\xfan m\xe1s general. Podr\xeda aplicarse a muchos problemas de optimizaci\xf3n, por lo que el art\xedculo es de amplio inter\xe9s."}),"\n",(0,o.jsx)(a.p,{children:"\xbfY por qu\xe9 pensamos que funcionar\xeda? El algoritmo que propusieron acelera la evoluci\xf3n para reducir la profundidad del circuito mientras suprime las transiciones no adiab\xe1ticas. Adem\xe1s, no depende de subrutinas de optimizaci\xf3n cl\xe1sica, las cuales pueden ser un problema que conduce a mesetas \xe1ridas y al estancamiento en m\xednimos locales. Finalmente, los autores tambi\xe9n se aseguran de alinear las interacciones en el hamiltoniano del problema con la conectividad del hardware en los QPUs reales, lo cual es siempre muy importante."}),"\n",(0,o.jsx)(a.p,{children:"\xbfC\xf3mo funciona este m\xe9todo entonces? De nuevo, no usa optimizadores cl\xe1sicos, a diferencia de la mayor\xeda de los otros algoritmos cu\xe1nticos iterativos. En su lugar, el algoritmo Bias-Field Digitized Quantum Optimization refina incrementalmente el estado fundamental y lo acerca cada vez m\xe1s al estado finalmente evolucionado, alimentando la soluci\xf3n de cada iteraci\xf3n como entrada para la siguiente. Combinado con los protocolos contradiab\xe1ticos, podemos hacer esto incluso con circuitos cu\xe1nticos de poca profundidad, que deber\xedan funcionar sin problemas en hardware ruidoso."}),"\n",(0,o.jsx)(a.p,{children:"Cuando se realiz\xf3 el experimento, los autores decidieron ejecutar el algoritmo en el computador cu\xe1ntico IBM de 127 qubits Brisbane. A continuaci\xf3n hay una figura que muestra la 8.\xaa iteraci\xf3n del algoritmo de optimizaci\xf3n para una instancia de vidrio de esp\xedn de vecinos m\xe1s cercanos generada aleatoriamente en 100 qubits. Comparan los resultados idealizados de simulaci\xf3n cl\xe1sica de DCQO y BF-DCQO, as\xed como el resultado experimental ejecutado en el computador cu\xe1ntico. Tambi\xe9n muestran el resultado de un solucionador cl\xe1sico llamado Gurobi como referencia. Con solo 10 iteraciones, BF-DCQO proporciona una mejora dr\xe1stica en comparaci\xf3n con DCQO. Aunque el resultado experimental es algo diferente del resultado ideal debido al ruido, el rendimiento sigue siendo mejor que el DCQO ideal. Esto demuestra que se siguen logrando avances significativos en la optimizaci\xf3n cu\xe1ntica y que se est\xe1n reportando buenos resultados para m\xe1s de 100 qubits en una de las primeras ocasiones."}),"\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.img,{alt:"Resultados del art\xedculo sobre el vidrio de esp\xedn de Ising",src:s(43410).A+"",width:"976",height:"682"})}),"\n",(0,o.jsx)(a.h3,{id:"use-case-3-mrna-secondary-structure-prediction",children:"Caso de uso 3: Predicci\xf3n de la estructura secundaria del ARNm"}),"\n",(0,o.jsxs)(a.p,{children:["Finalmente, discutiremos un art\xedculo de Moderna Pharmaceuticals titulado ",(0,o.jsx)(a.a,{href:"https://arxiv.org/abs/2405.20328",children:"mRNA Secondary Structure Prediction Using Utility-Scale Quantum Computers"}),"."]}),"\n",(0,o.jsx)(a.p,{children:"Primero, un breve repaso sobre el ARNm. El ARN mensajero es un tipo de ARN involucrado en la s\xedntesis de prote\xednas. Esencialmente, lee las instrucciones dadas por el ADN. La estructura secundaria del ARNm es c\xf3mo se pliega la cadena, como se muestra en el diagrama de abajo. Y el problema de predicci\xf3n de la estructura secundaria del ARNm es el problema de encontrar el plegamiento m\xe1s estable de la secuencia de bases o nucle\xf3tidos que componen el ARN: adenina (A), citosina (C), uracilo (U) y guanina (G). La imagen de abajo muestra algunas estructuras de plegamiento comunes que se encuentran en el ARNm; cada color representa un tipo diferente de estructura secundaria. Lo que hace que una estructura sea m\xe1s favorable que las otras no se comprende bien; solo podemos calcular qu\xe9 estructura produce la menor energ\xeda libre en comparaci\xf3n con el estado desplegado. Y aqu\xed es exactamente donde entran los computadores cu\xe1nticos."}),"\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.img,{alt:"Diagrama de la estructura secundaria del ARNm",src:s(41923).A+"",width:"638",height:"842"})}),"\n",(0,o.jsx)(a.p,{children:"Entonces, \xbfpor qu\xe9 son importantes las estructuras secundarias del ARNm? Una predicci\xf3n precisa de estas no solo es crucial para comprender el ADN y nuestros genes, sino tambi\xe9n para el dise\xf1o de terapias basadas en ARN, como la vacuna contra el COVID-19."}),"\n",(0,o.jsx)(a.p,{children:"Se sabe desde hace mucho tiempo que este es un enorme problema de optimizaci\xf3n para los computadores cl\xe1sicos, debido a la gran cantidad de configuraciones posibles. Para algunas configuraciones, se sabe que es un problema NP-completo. Sin embargo, en un computador cu\xe1ntico podemos formular la predicci\xf3n de la estructura secundaria como un problema de optimizaci\xf3n binaria -- algo que sabemos c\xf3mo manejar. Adem\xe1s, ya hab\xeda evidencia en la literatura de predicciones precisas de ARN en peque\xf1os dispositivos cu\xe1nticos y simuladores cu\xe1nticos. Pero, \xbffuncionar\xeda tambi\xe9n en hardware m\xe1s grande?"}),"\n",(0,o.jsx)(a.p,{children:"Este experimento se realiz\xf3 con el llamado Conditional Value at Risk Variational Quantum Eigensolver, que es una modificaci\xf3n de un algoritmo VQE tradicional y del que se espera lograr una mejor convergencia."}),"\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.img,{alt:"Resultados del art\xedculo sobre ARNm",src:s(65188).A+"",width:"1158",height:"686"})}),"\n",(0,o.jsx)(a.p,{children:"El gr\xe1fico de arriba muestra la distribuci\xf3n de las probabilidades de medici\xf3n de las cadenas de bits muestreadas con las energ\xedas correspondientes para una instancia de 42 nucle\xf3tidos y 80 qubits. Aqu\xed las cadenas de bits simbolizan emparejamientos de nucle\xf3tidos. Muestra que la cadena de bits de menor energ\xeda que encontr\xf3 el computador cu\xe1ntico coincide con la del solucionador cl\xe1sico de comparaci\xf3n -- esto es excelente. Tambi\xe9n se muestra la estructura de plegamiento \xf3ptima de esta cadena de nucle\xf3tidos basada en la cadena de bits de menor energ\xeda encontrada por el computador cu\xe1ntico."}),"\n",(0,o.jsx)(a.h2,{id:"conclusion",children:"Conclusi\xf3n"}),"\n",(0,o.jsx)(a.p,{children:"Esperamos que estos tres casos de uso te hayan dado suficiente contexto para entender c\xf3mo se ve el trabajo de vanguardia en este campo actualmente, y la confianza para probar nuevos experimentos cu\xe1nticos que quiz\xe1s no habr\xedas intentado antes."}),"\n",(0,o.jsx)(a.p,{children:"Recuerda: la computaci\xf3n cu\xe1ntica no es adecuada para todos los problemas. Y eso es en realidad solo un testimonio de lo buenos que nos hemos vuelto en la computaci\xf3n cl\xe1sica. Solo porque creas que puedes aplicar la computaci\xf3n cu\xe1ntica a un problema no significa que producir\xe1 resultados interesantes; debes considerar la escalabilidad."}),"\n",(0,o.jsx)(a.p,{children:"La profundidad del circuito es un arma de doble filo. La necesitamos para hacer un trabajo interesante que los computadores cl\xe1sicos no pueden hacer, pero por ahora no podemos aumentar demasiado la profundidad porque el ruido del hardware reducir\xe1 la fidelidad. Se trata de encontrar ese punto \xf3ptimo y saber que es un objetivo en movimiento. As\xed que t\xf3mate un tiempo hasta la pr\xf3xima lecci\xf3n para pensar en un problema que hayas encontrado en tu investigaci\xf3n y c\xf3mo podr\xedas abordarlo con lo que hemos aprendido hasta ahora. Y oye, tu soluci\xf3n no tiene por qu\xe9 funcionar, y eso est\xe1 bien. Para eso hacemos investigaci\xf3n."})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},52600(e,a,s){s.d(a,{A:()=>n});const n=s.p+"assets/images/complexity_classes-52979b588e98706373f7abc9b3f5f57c.avif"},77894(e,a,s){s.d(a,{A:()=>n});const n=s.p+"assets/images/hadron_paper-bc9c0a13fc3cd0e44b5c193902ce6dba.avif"},65188(e,a,s){s.d(a,{A:()=>n});const n=s.p+"assets/images/mrna_paper-4b1d694275f2539f69c49bfbb9b5ddd8.avif"},41923(e,a,s){s.d(a,{A:()=>n});const n=s.p+"assets/images/mrna_structure-962f2d5dfb98ac0a2e9c680e23d97ada.avif"},43410(e,a,s){s.d(a,{A:()=>n});const n=s.p+"assets/images/paper_results-aace6d8c4b97868e6cba7fc772e13ad9.avif"},28453(e,a,s){s.d(a,{R:()=>r,x:()=>c});var n=s(96540);const o={},i=n.createContext(o);function r(e){const a=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),n.createElement(i.Provider,{value:a},e.children)}}}]);